package io.reactivex.rxjava3.internal.operators.observable;

import java.util.Objects;
import java.util.concurrent.atomic.*;

import io.reactivex.rxjava3.core.*;
import io.reactivex.rxjava3.disposables.Disposable;
import io.reactivex.rxjava3.exceptions.Exceptions;
import io.reactivex.rxjava3.functions.Function;
import io.reactivex.rxjava3.internal.disposables.DisposableHelper;
import io.reactivex.rxjava3.internal.util.AtomicThrowable;
import io.reactivex.rxjava3.operators.QueueDisposable;
import io.reactivex.rxjava3.operators.SimpleQueue;
import io.reactivex.rxjava3.operators.SpscLinkedArrayQueue;
import io.reactivex.rxjava3.plugins.RxJavaPlugins;

public final class ObservableSwitchMap<T, R> extends AbstractObservableWithUpstream<T, R> {
    final Function<? super T, ? extends ObservableSource<? extends R>> mapper;
    final int bufferSize;

    final boolean delayErrors;

    public ObservableSwitchMap(ObservableSource<T> source,
                               Function<? super T, ? extends ObservableSource<? extends R>> mapper, int bufferSize,
                                       boolean delayErrors) {
        super(source);
        this.mapper = mapper;
        this.bufferSize = bufferSize;
        this.delayErrors = delayErrors;
    }

    @Override
    public void subscribeActual(Observer<? super R> t) {

        if (ObservableScalarXMap.tryScalarXMapSubscribe(source, t, mapper)) {
            return;
        }

        source.subscribe(new SwitchMapObserver<>(t, mapper, bufferSize, delayErrors));
    }

    static final class SwitchMapObserver<T, R> extends AtomicInteger implements Observer<T>, Disposable {

        private static final long serialVersionUID = -3491074160481096299L;
        final Observer<? super R> downstream;
        final Function<? super T, ? extends ObservableSource<? extends R>> mapper;
        final int bufferSize;

        final boolean delayErrors;

        final AtomicThrowable errors;

        volatile boolean done;

        volatile boolean cancelled;

        Disposable upstream;

        final AtomicReference<SwitchMapInnerObserver<T, R>> active = new AtomicReference<>();

        static final SwitchMapInnerObserver<Object, Object> CANCELLED;
        static {
            CANCELLED = new SwitchMapInnerObserver<>(null, -1L, 1);
            CANCELLED.cancel();
        }

        volatile long unique;

        SwitchMapObserver(Observer<? super R> actual,
                Function<? super T, ? extends ObservableSource<? extends R>> mapper, int bufferSize,
                        boolean delayErrors) {
            this.downstream = actual;
            this.mapper = mapper;
            this.bufferSize = bufferSize;
            this.delayErrors = delayErrors;
            this.errors = new AtomicThrowable();
        }

        @Override
        public void onSubscribe(Disposable d) {
            if (DisposableHelper.validate(this.upstream, d)) {
                this.upstream = d;
                downstream.onSubscribe(this);
            }
        }

        @Override
        public void onNext(T t) {
            long c = unique + 1;
            unique = c;

            SwitchMapInnerObserver<T, R> inner = active.get();
            if (inner != null) {
                inner.cancel();
            }

            ObservableSource<? extends R> p;
            try {
                p = Objects.requireNonNull(mapper.apply(t), "The ObservableSource returned is null");
            } catch (Throwable e) {
                Exceptions.throwIfFatal(e);
                upstream.dispose();
                onError(e);
                return;
            }

            SwitchMapInnerObserver<T, R> nextInner = new SwitchMapInnerObserver<>(this, c, bufferSize);

            for (;;) {
                inner = active.get();
                if (inner == CANCELLED) {
                    break;
                }
                if (active.compareAndSet(inner, nextInner)) {
                    p.subscribe(nextInner);
                    break;
                }
            }
        }

        @Override
        public void onError(Throwable t) {
            if (!done && errors.tryAddThrowable(t)) {
                if (!delayErrors) {
                    disposeInner();
                }
                done = true;
                drain();
            } else {
                RxJavaPlugins.onError(t);
            }
        }

        @Override
        public void onComplete() {
            if (!done) {
                done = true;
                drain();
            }
        }

        @Override
        public void dispose() {
            if (!cancelled) {
                cancelled = true;
                upstream.dispose();
                disposeInner();

                errors.tryTerminateAndReport();
            }
        }

        @Override
        public boolean isDisposed() {
            return cancelled;
        }

        @SuppressWarnings("unchecked")
        void disposeInner() {
            SwitchMapInnerObserver<T, R> a = active.getAndSet((SwitchMapInnerObserver<T, R>)CANCELLED);
            if (a != null) {
                a.cancel();
            }
        }

        void drain() {
            if (getAndIncrement() != 0) {
                return;
            }

            final Observer<? super R> a = downstream;
            final AtomicReference<SwitchMapInnerObserver<T, R>> active = this.active;
            final boolean delayErrors = this.delayErrors;

            int missing = 1;

            for (;;) {

                if (cancelled) {
                    return;
                }

                if (done) {
                    boolean empty = active.get() == null;
                    if (delayErrors) {
                        if (empty) {
                            Throwable ex = errors.get();
                            if (ex != null) {
                                a.onError(ex);
                            } else {
                                a.onComplete();
                            }
                            return;
                        }
                    } else {
                        Throwable ex = errors.get();
                        if (ex != null) {
                            errors.tryTerminateConsumer(a);
                            return;
                        }
                        if (empty) {
                            a.onComplete();
                            return;
                        }
                    }
                }

                SwitchMapInnerObserver<T, R> inner = active.get();

                if (inner != null) {
                    SimpleQueue<R> q = inner.queue;

                    if (q != null) {

                        boolean retry = false;

                        for (;;) {
                            if (cancelled) {
                                return;
                            }
                            if (inner != active.get()) {
                                retry = true;
                                break;
                            }

                            if (!delayErrors) {
                                Throwable ex = errors.get();
                                if (ex != null) {
                                    errors.tryTerminateConsumer(a);
                                    return;
                                }
                            }

                            boolean d = inner.done;
                            R v;

                            try {
                                v = q.poll();
                            } catch (Throwable ex) {
                                Exceptions.throwIfFatal(ex);
                                errors.tryAddThrowableOrReport(ex);
                                active.compareAndSet(inner, null);
                                if (!delayErrors) {
                                    disposeInner();
                                    upstream.dispose();
                                    done = true;
                                } else {
                                    inner.cancel();
                                }
                                v = null;
                                retry = true;
                            }
                            boolean empty = v == null;

                            if (d && empty) {
                                active.compareAndSet(inner, null);
                                retry = true;
                                break;
                            }

                            if (empty) {
                                break;
                            }

                            a.onNext(v);
                        }

                        if (retry) {
                            continue;
                        }
                    }
                }

                missing = addAndGet(-missing);
                if (missing == 0) {
                    break;
                }
            }
        }

        void innerError(SwitchMapInnerObserver<T, R> inner, Throwable ex) {
            if (inner.index == unique && errors.tryAddThrowable(ex)) {
                if (!delayErrors) {
                    upstream.dispose();
                    done = true;
                }
                inner.done = true;
                drain();
            } else {
                RxJavaPlugins.onError(ex);
            }
        }
    }

    static final class SwitchMapInnerObserver<T, R> extends AtomicReference<Disposable> implements Observer<R> {

        private static final long serialVersionUID = 3837284832786408377L;
        final SwitchMapObserver<T, R> parent;
        final long index;

        final int bufferSize;

        volatile SimpleQueue<R> queue;

        volatile boolean done;

        SwitchMapInnerObserver(SwitchMapObserver<T, R> parent, long index, int bufferSize) {
            this.parent = parent;
            this.index = index;
            this.bufferSize = bufferSize;
        }

        @Override
        public void onSubscribe(Disposable d) {
            if (DisposableHelper.setOnce(this, d)) {
                if (d instanceof QueueDisposable) {
                    @SuppressWarnings("unchecked")
                    QueueDisposable<R> qd = (QueueDisposable<R>) d;

                    int m = qd.requestFusion(QueueDisposable.ANY | QueueDisposable.BOUNDARY);
                    if (m == QueueDisposable.SYNC) {
                        queue = qd;
                        done = true;
                        parent.drain();
                        return;
                    }
                    if (m == QueueDisposable.ASYNC) {
                        queue = qd;
                        return;
                    }
                }

                queue = new SpscLinkedArrayQueue<>(bufferSize);
            }
        }

        @Override
        @SuppressWarnings("unchecked")
        public void onNext(R t) {
            SwitchMapObserver<T, R> parentObserver = parent;
            long currentIndex = index;
            long parentIndex = parentObserver.unique;
            if (currentIndex != parentIndex) {
                return;
            }
            if (t != null) {
                SimpleQueue<R> innerQueue = queue;
                if (innerQueue instanceof SpscLinkedArrayQueue) {
                    SpscLinkedArrayQueue<R> spscQueue = (SpscLinkedArrayQueue<R>) innerQueue;
                    spscQueue.offer(t);
                } else if (innerQueue instanceof QueueDisposable) {
                    QueueDisposable<R> fusedQueue = (QueueDisposable<R>) innerQueue;
                    fusedQueue.offer(t);
                } else {
                    innerQueue.offer(t);
                }
            }
            int previousWork = parentObserver.getAndIncrement();
            if (previousWork != 0) {
                return;
            } else {
                Observer<? super R> downstreamObserver = parentObserver.downstream;
                AtomicReference<SwitchMapInnerObserver<T, R>> activeInner = parentObserver.active;
                AtomicThrowable sharedErrors = parentObserver.errors;
                Disposable upstreamDisposable = parentObserver.upstream;
                boolean delayErrors = parentObserver.delayErrors;
                if (delayErrors) {
                    int missed = 1;
                    for (;;) {
                        boolean cancelledNow = parentObserver.cancelled;
                        if (cancelledNow) {
                            return;
                        }
                        boolean mainCompleted = parentObserver.done;
                        if (mainCompleted) {
                            SwitchMapInnerObserver<T, R> currentActive = activeInner.get();
                            boolean noActiveInner = currentActive == null;
                            if (noActiveInner) {
                                Throwable terminalError = sharedErrors.get();
                                if (terminalError != null) {
                                    downstreamObserver.onError(terminalError);
                                    return;
                                }
                                downstreamObserver.onComplete();
                                return;
                            }
                        }
                        SwitchMapInnerObserver<T, R> inner = activeInner.get();
                        if (inner != null) {
                            SimpleQueue<R> sourceQueue = inner.queue;
                            if (sourceQueue != null) {
                                boolean retry = false;
                                for (;;) {
                                    boolean innerCancelled = parentObserver.cancelled;
                                    if (innerCancelled) {
                                        return;
                                    }
                                    boolean switchedInner = inner != activeInner.get();
                                    if (switchedInner) {
                                        retry = true;
                                        break;
                                    }
                                    boolean innerDone = inner.done;
                                    R value = null;
                                    try {
                                        if (sourceQueue instanceof SpscLinkedArrayQueue) {
                                            SpscLinkedArrayQueue<R> spscSource = (SpscLinkedArrayQueue<R>) sourceQueue;
                                            value = spscSource.poll();
                                        } else if (sourceQueue instanceof QueueDisposable) {
                                            QueueDisposable<R> fusedSource = (QueueDisposable<R>) sourceQueue;
                                            value = fusedSource.poll();
                                        } else {
                                            value = sourceQueue.poll();
                                        }
                                    } catch (Throwable ex) {
                                        boolean fatalVirtualMachineError = ex instanceof VirtualMachineError;
                                        if (fatalVirtualMachineError) {
                                            throw (VirtualMachineError) ex;
                                        }
                                        boolean fatalThreadDeath = ex instanceof ThreadDeath;
                                        if (fatalThreadDeath) {
                                            throw (ThreadDeath) ex;
                                        }
                                        boolean fatalLinkageError = ex instanceof LinkageError;
                                        if (fatalLinkageError) {
                                            throw (LinkageError) ex;
                                        }
                                        if (!sharedErrors.tryAddThrowable(ex)) {
                                            RxJavaPlugins.onError(ex);
                                        }
                                        activeInner.compareAndSet(inner, null);
                                        Disposable current = inner.get();
                                        if (current != DisposableHelper.DISPOSED) {
                                            current = inner.getAndSet(DisposableHelper.DISPOSED);
                                        }
                                        if (current != null && current != DisposableHelper.DISPOSED) {
                                            current.dispose();
                                        }
                                        value = null;
                                        retry = true;
                                    }
                                    boolean empty = value == null;
                                    if (innerDone && empty) {
                                        activeInner.compareAndSet(inner, null);
                                        retry = true;
                                        break;
                                    }
                                    if (empty) {
                                        break;
                                    }
                                    downstreamObserver.onNext(value);
                                }
                                if (retry) {
                                    continue;
                                }
                            }
                        }
                        int remainingWork = parentObserver.addAndGet(-missed);
                        missed = remainingWork;
                        boolean continueDraining = missed != 0;
                        if (!continueDraining) {
                            break;
                        }
                    }
                } else {
                    int missed = 1;
                    for (;;) {
                        boolean cancelledNow = parentObserver.cancelled;
                        if (cancelledNow) {
                            return;
                        }
                        boolean mainCompleted = parentObserver.done;
                        if (mainCompleted) {
                            SwitchMapInnerObserver<T, R> currentActive = activeInner.get();
                            boolean noActiveInner = currentActive == null;
                            Throwable terminalError = sharedErrors.get();
                            if (terminalError != null) {
                                sharedErrors.tryTerminateConsumer(downstreamObserver);
                                return;
                            }
                            if (noActiveInner) {
                                downstreamObserver.onComplete();
                                return;
                            }
                        }
                        SwitchMapInnerObserver<T, R> inner = activeInner.get();
                        if (inner != null) {
                            SimpleQueue<R> sourceQueue = inner.queue;
                            if (sourceQueue != null) {
                                boolean retry = false;
                                for (;;) {
                                    boolean innerCancelled = parentObserver.cancelled;
                                    if (innerCancelled) {
                                        return;
                                    }
                                    boolean switchedInner = inner != activeInner.get();
                                    if (switchedInner) {
                                        retry = true;
                                        break;
                                    }
                                    Throwable pendingError = sharedErrors.get();
                                    if (pendingError != null) {
                                        sharedErrors.tryTerminateConsumer(downstreamObserver);
                                        return;
                                    }
                                    boolean innerDone = inner.done;
                                    R value = null;
                                    try {
                                        if (sourceQueue instanceof SpscLinkedArrayQueue) {
                                            SpscLinkedArrayQueue<R> spscSource = (SpscLinkedArrayQueue<R>) sourceQueue;
                                            value = spscSource.poll();
                                        } else if (sourceQueue instanceof QueueDisposable) {
                                            QueueDisposable<R> fusedSource = (QueueDisposable<R>) sourceQueue;
                                            value = fusedSource.poll();
                                        } else {
                                            value = sourceQueue.poll();
                                        }
                                    } catch (Throwable ex) {
                                        boolean fatalVirtualMachineError = ex instanceof VirtualMachineError;
                                        if (fatalVirtualMachineError) {
                                            throw (VirtualMachineError) ex;
                                        }
                                        boolean fatalThreadDeath = ex instanceof ThreadDeath;
                                        if (fatalThreadDeath) {
                                            throw (ThreadDeath) ex;
                                        }
                                        boolean fatalLinkageError = ex instanceof LinkageError;
                                        if (fatalLinkageError) {
                                            throw (LinkageError) ex;
                                        }
                                        if (!sharedErrors.tryAddThrowable(ex)) {
                                            RxJavaPlugins.onError(ex);
                                        }
                                        activeInner.compareAndSet(inner, null);
                                        SwitchMapInnerObserver<T, R> cancelledInner =
                                                parentObserver.active.getAndSet((SwitchMapInnerObserver<T, R>) SwitchMapObserver.CANCELLED);
                                        Disposable current = null;
                                        if (cancelledInner != null) {
                                            current = cancelledInner.get();
                                        }
                                        if (cancelledInner != null && current != DisposableHelper.DISPOSED) {
                                            current = cancelledInner.getAndSet(DisposableHelper.DISPOSED);
                                        }
                                        if (current != null && current != DisposableHelper.DISPOSED) {
                                            current.dispose();
                                        }
                                        if (upstreamDisposable != null) {
                                            upstreamDisposable.dispose();
                                        }
                                        parentObserver.done = true;
                                        value = null;
                                        retry = true;
                                    }
                                    boolean empty = value == null;
                                    if (innerDone && empty) {
                                        activeInner.compareAndSet(inner, null);
                                        retry = true;
                                        break;
                                    }
                                    if (empty) {
                                        break;
                                    }
                                    downstreamObserver.onNext(value);
                                }
                                if (retry) {
                                    continue;
                                }
                            }
                        }
                        int remainingWork = parentObserver.addAndGet(-missed);
                        missed = remainingWork;
                        boolean continueDraining = missed != 0;
                        if (!continueDraining) {
                            break;
                        }
                    }
                }
            }
        }


        @Override
        public void onError(Throwable t) {
            parent.innerError(this, t);
        }

        @Override
        public void onComplete() {
            if (index == parent.unique) {
                done = true;
                parent.drain();
            }
        }

        public void cancel() {
            DisposableHelper.dispose(this);
        }
    }
}

